"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["28853"],{27745(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>d,frontMatter:()=>r,contentTitle:()=>o,toc:()=>c,assets:()=>h});var s=JSON.parse('{"id":"tangfen/tosiwen2","title":"","description":"Siwen is at it again with his taken-for-granted assumptions. In Miss Chan\'s post \\"Strange, why can\'t Gao Tianhu be suspected of perjury?\\", the three characters for \\"crime of perjury\\" never appear. Miss Chan only says \\"suspected of perjury\\" -- in plainer terms, \\"suspected of fabricating evidence.\\" But Siwen assumes this means what he calls \\"the crime of perjury.\\" How incredibly presumptuous.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/tosiwen2.md","sourceDirName":"tangfen","slug":"/tangfen/tosiwen2","permalink":"/en/tangfen/tosiwen2","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"tosiwen2","title":"","hide_table_of_contents":true,"sidebar_label":"Siwen, who told you that Ms. Chan\'s suspected perjury is the \\"crime of perjury\\" you describe?"},"sidebar":"tangfenSidebar","previous":{"title":"[Siwen], don\'t habitually fabricate things out of thin air in discussions!","permalink":"/en/tangfen/tosiwen"},"next":{"title":"An elementary school math lesson for the likes of Yunguzhi!","permalink":"/en/tangfen/abasicmathlecture"}}'),i=n(74848),a=n(28453);let r={id:"tosiwen2",title:"",hide_table_of_contents:!0,sidebar_label:'Siwen, who told you that Ms. Chan\'s suspected perjury is the "crime of perjury" you describe?'},o='Siwen, Who Told You That Miss Chan\'s "Suspected of Perjury" Means Your So-Called "Crime of Perjury"?',h={},c=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"siwen-who-told-you-that-miss-chans-suspected-of-perjury-means-your-so-called-crime-of-perjury",children:'Siwen, Who Told You That Miss Chan\'s "Suspected of Perjury" Means Your So-Called "Crime of Perjury"?'})}),"\n",(0,i.jsx)(t.p,{children:'Siwen is at it again with his taken-for-granted assumptions. In Miss Chan\'s post "Strange, why can\'t Gao Tianhu be suspected of perjury?", the three characters for "crime of perjury" never appear. Miss Chan only says "suspected of perjury" -- in plainer terms, "suspected of fabricating evidence." But Siwen assumes this means what he calls "the crime of perjury." How incredibly presumptuous.'}),"\n",(0,i.jsx)(t.p,{children:"Everyone knows that for a crime to be established, facts must be established. If someone is \"suspected of fabricating evidence\" but hasn't used that evidence to commit a criminal act, it doesn't constitute \"the crime of perjury.\" Using Gao's father's example: if he merely put his own material on the underpants but didn't use this material to accuse anyone, then of course it doesn't constitute a crime. But he is still \"suspected of fabricating evidence,\" because he told everyone he had a piece of evidence with the criminal's material on it, when in fact the material was put there by himself -- meaning he fabricated the evidence he claimed to have. Since whether this fabrication of evidence is actually true hasn't been finally confirmed, it's called \"suspected.\" Miss Chan's logic here is very clear."}),"\n",(0,i.jsx)(t.p,{children:'But Siwen fundamentally can\'t grasp the difference between "suspected of fabricating evidence" and "the crime of perjury." He thinks Miss Chan saying "suspected of fabricating evidence" means she\'s saying "the crime of perjury." This only exposes his own confusion! Precisely because of this confusion, everything he wrote about "the crime of perjury" in his posts becomes completely off-target, having nothing whatsoever to do with Miss Chan. Because Miss Chan never said anything about "the crime of perjury"!'}),"\n",(0,i.jsx)(t.p,{children:'The reason I spend my days defending Miss Chan and Marx is that certain people constantly first distort others\' statements, then launch off-target tirades at length. This behavior is extremely abnormal yet extremely common, which is why I have no choice but to step forward and defend Miss Chan and Marx! For example, in the case of Marx, that Yunguzi fellow actually slandered Marx as denying the exchangeability of commodities. This time Siwen slandered Miss Chan as saying "the crime of perjury." What does this demonstrate? Everyone can ponder deeply!'})]})}function d(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var s=n(96540);let i={},a=s.createContext(i);function r(e){let t=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),s.createElement(a.Provider,{value:t},e.children)}}}]);